<section class="page-hero"><div class="container"><p class="eyebrow">Create</p><h1>Media</h1><p><?= e($copy['media_intro']) ?></p></div></section><section class="section container"><div class="public-grid"><?php foreach(array_slice(xuverse_content('media'),0,3) as $m): ?><article class="public-card"><?php parse_str(parse_url($m['url'],PHP_URL_QUERY),$thumbnailQuery); ?><a href="<?= e(xuverse_url('videos/'.$m['slug'])) ?>"><img src="https://i.ytimg.com/vi/<?= e($thumbnailQuery['v']) ?>/hqdefault.jpg" alt="<?= e($m['title']) ?> video thumbnail" width="480" height="360" loading="lazy" decoding="async"></a><p class="eyebrow">Video</p><h2><a href="<?= e(xuverse_url('videos/'.$m['slug'])) ?>"><?= e($m['title']) ?></a></h2><p><?= e($m['summary']) ?></p><a class="text-link" href="<?= e(xuverse_url('videos/'.$m['slug'])) ?>">Watch video →</a></article><?php endforeach; ?></div><?php $cards=xuverse_content('media')[3]; ?><section class="section" id="anchor-eco-delta"><p class="eyebrow">Visual communication</p><h2><?= e($cards['title']) ?></h2><p><?= e($cards['summary']) ?></p><p><?= e($cards['credit_note']) ?></p><div class="public-grid card-series"><?php foreach($cards['cards'] as $i=>$card): ?><figure><a href="<?= e(xuverse_url($card)) ?>"><img src="<?= e(xuverse_url($card)) ?>" alt="ANCHOR Eco Delta Smart City card <?= $i+1 ?>, with original embedded credits" loading="lazy" decoding="async"></a><figcaption>Card <?= $i+1 ?> · Original credits retained. Open full size to read.</figcaption></figure><?php endforeach; ?></div></section></section><?php include 'includes/footer.php'; ?>
